source='''def transform(grid):
    height, width = len(grid), len(grid[0])

    def dominant_nonzero(values):
        colors = {value for value in values if value != 0}
        return max(((sum(value == color for value in values), color) for color in colors), default=(0, 0))

    vertical = []
    for c in range(width):
        count, color = dominant_nonzero([grid[r][c] for r in range(height)])
        if count > height // 2:
            vertical.append(c)
    vertical_set = set(vertical)

    horizontal = []
    for r in range(height):
        count, color = dominant_nonzero([grid[r][c] for c in range(width) if c not in vertical_set])
        if count > (width - len(vertical)) // 2:
            horizontal.append(r)

    def representatives(size, separators):
        chosen = []
        start = 0
        for line in separators:
            if start < line:
                chosen.append(start)
            chosen.append(line)
            start = line + 1
        if start < size:
            chosen.append(start)
        return chosen

    rows = representatives(height, horizontal)
    cols = representatives(width, vertical)
    return [[grid[r][c] for c in cols] for r in rows]
'''
